import numpy as np
from scipy.optimize import minimize
import time

# --- Constants ---
N = 26
R_MIN = 1e-6
SAFETY = 1e-9

# --- Helper Functions (from lineage, e.g., Eval 749) ---
def cr_to_z(c, r): return np.concatenate([c.flatten(), r])
def z_to_cr(z): return z[:N*2].reshape(N, 2), z[N*2:]

def _ensure_validity(c, r):
    for i in range(N): r[i] = min(r[i], c[i,0], 1-c[i,0], c[i,1], 1-c[i,1])
    for _ in range(10):
        violations = 0
        for i in range(N):
            for j in range(i + 1, N):
                dist = np.linalg.norm(c[i] - c[j])
                rad_sum = r[i] + r[j]
                if dist < rad_sum:
                    violations+=1; scale = (dist/rad_sum)*(1.0-SAFETY); r[i]*=scale; r[j]*=scale
        if violations == 0: break
    return c, np.maximum(r, 0)

# --- New Geometric Seeding Function ---
def generate_spiral_seed():
    """Generates centers along an Archimedean spiral."""
    centers = np.zeros((N, 2))
    # Spiral parameters tuned to spread points within the unit square
    a = 0.0
    b = 0.04

    for i in range(N):
        angle = np.sqrt(i) * 3.6 # Spread out points
        radius = a + b * angle
        centers[i, 0] = 0.5 + radius * np.cos(angle)
        centers[i, 1] = 0.5 + radius * np.sin(angle)

    # Clip to be strictly within bounds to avoid starting on the edge
    centers = np.clip(centers, 0.01, 0.99)

    # Use a small, uniform initial radius for all circles
    initial_radii = np.full(N, 0.05)

    return centers, initial_radii

# --- SLSQP Definitions (from lineage, e.g., Eval 749) ---
def objective(z): return -np.sum(z[N*2:])
def ineq_boundary(z):
    c, r = z_to_cr(z)
    return np.concatenate([c[:,0] - r, 1 - (c[:,0] + r), c[:,1] - r, 1 - (c[:,1] + r)])
def ineq_nonoverlap(z):
    c, r = z_to_cr(z)
    diff = c[:, None, :] - c[None, :, :]
    dist = np.sqrt(np.sum(diff**2, axis=-1))
    iu = np.triu_indices(N, 1)
    return dist[iu] - (r[iu[0]] + r[iu[1]])

def construct_packing() -> tuple:
    start_time = time.time()

    # Generate the single, deterministic seed
    initial_centers, initial_radii = generate_spiral_seed()
    initial_z = cr_to_z(initial_centers, initial_radii)

    bounds = [(0,1)]*N*2 + [(R_MIN, 0.5)]*N
    constraints = [{'type': 'ineq', 'fun': ineq_boundary}, {'type': 'ineq', 'fun': ineq_nonoverlap}]

    res = minimize(objective, initial_z, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 2000, 'ftol': 1e-9})

    if res.success:
        final_centers, final_radii = z_to_cr(res.x)
        return _ensure_validity(final_centers, final_radii)
    else:
        # Fallback to the initial seed if optimization fails
        return _ensure_validity(initial_centers, initial_radii)
